(function(){"use strict";const h=["Mon","Tue","Wed","Thu","Fri"];self.onmessage=f=>{const{selectedLectures:a,goodSlots:l,badSlots:o,weights:t}=f.data,s={};a.forEach(e=>{s[e.name]||(s[e.name]=[]),s[e.name].push(e)});const n=Object.values(s),c=[];if(n.length>0){const e=new Array(n.length).fill(0);for(;;){const r=[];for(let i=0;i<n.length;i++)r.push(n[i][e[i]]);if(!p(r)){const i=m(r,l,o,t);c.push({lectures:[...r],score:i})}let u=n.length-1;for(;u>=0&&e[u]+1>=n[u].length;)e[u]=0,u--;if(u<0)break;e[u]++}}c.sort((e,r)=>e.score-r.score),self.postMessage(c)};function p(f){const a={Mon:new Set,Tue:new Set,Wed:new Set,Thu:new Set,Fri:new Set};for(const l of f)for(const o of l.time_slots){const t=a[o.day];for(let s=o.start_index;s<=o.end_index;s++){if(t.has(s))return!0;t.add(s)}}return!1}function m(f,a,l,o){const t={Mon:new Set,Tue:new Set,Wed:new Set,Thu:new Set,Fri:new Set};for(const u of f)for(const i of u.time_slots)for(let d=i.start_index;d<=i.end_index;d++)t[i.day].add(d);const s=S(t,a,o[0].rss),n=S(t,l,o[1].rss),c=g(t,o[2].rss),e=f.reduce((u,i)=>u+i.preference,0);let r=0;return r+=s*o[0].weight*-1,r+=n*o[1].weight,r+=c*o[2].weight,r+=e*o[3].weight*-1,r}function S(f,a,l){const o=[];for(const t of h){const s=f[t],n=a[t]||[];let c=0;for(const e of n)s.has(e)&&c++;o.push(c)}return l?Math.sqrt(o.reduce((t,s)=>t+s*s,0)):o.reduce((t,s)=>t+s,0)}function g(f,a){const l=[];for(const o of h){const t=Array.from(f[o]).sort((e,r)=>e-r);if(t.length===0){l.push(0);continue}let s=0;const n=[];let c=[t[0]];for(let e=1;e<t.length;e++)t[e]===t[e-1]+1?c.push(t[e]):(n.push(c),c=[t[e]]);if(n.push(c),n.length>1)for(let e=0;e<n.length-1;e++)s+=n[e+1][0]-n[e][n[e].length-1]-1;l.push(s)}return a?Math.sqrt(l.reduce((o,t)=>o+t*t,0)):l.reduce((o,t)=>o+t,0)}})();
